contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 minDelay,
        address other,
        uint256 delay,
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt,
        address executor,
        uint256 execDelay
    ) public payable {
        require(delay >= minDelay, "pre: schedule delay sufficient");
        require(target != address(c), "pre: no self-call");
        if (!c.hasRole(c.EXECUTOR_ROLE(), address(0))) {
            c.grantRole(c.EXECUTOR_ROLE(), executor);
        }

        bool schReverted;
        try c.schedule(target, value, data, predecessor, salt, delay) { schReverted = false; } catch { schReverted = true; }
        require(!schReverted, "pre: schedule succeeded");

        uint256 tsBefore = c.getTimestamp(c.hashOperation(target, value, data, predecessor, salt));

        bool reverted;
        try c.execute(target, value, data, predecessor, salt) { reverted = false; } catch { reverted = true; }

        uint256 tsAfter = c.getTimestamp(c.hashOperation(target, value, data, predecessor, salt));
        assert(reverted || tsAfter == 1 || tsAfter > tsBefore);
    }

    receive() external payable {}
}

