contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 delay,
        address target,
        uint256 value,
        bytes calldata data,
        bytes32 predecessor,
        bytes32 salt
    ) public payable {
        require(delay >= c.getMinDelay(), "pre: sufficient delay");

        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        require(!c.isOperation(id), "pre: operation not already scheduled");

        c.schedule(target, value, data, predecessor, salt, delay);

        uint256 tsBefore = c.getTimestamp(id);
        require(tsBefore > block.timestamp, "pre: operation not yet ready");

        bool reverted;
        try c.execute(target, value, data, predecessor, salt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 tsAfter = c.getTimestamp(id);
        assert(reverted || tsAfter == tsBefore);
    }

    receive() external payable {}
}

