contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 newDelay) public payable {
        require(true);

        uint256 before = c.getMinDelay();

        bool reverted;
        try c.updateDelay(newDelay) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterDelay = c.getMinDelay();

        assert(reverted && afterDelay == before);
    }

    receive() external payable {}
}
